{
  "stg_salesforce__account": {
    "items": [],
    "fewer_reason": "The final implementation visibly covers the supplied account validation rules, and observed account IDs are unique; no additional concrete concern was found."
  },
  "stg_salesforce__contact": {
    "items": [
      {
        "problem": "The staging query does not enforce the required non-null last_name and contact_name fields.",
        "about": "requirement",
        "evidence_in_work": "filters=['id is not null',\"regexp_matches(id, '^[A-Za-z0-9]{15,18}$')\",'not coalesce(is_deleted, false)']",
        "source": "last_name ... constraints: [not_null]; contact_name ... constraints: [not_null]",
        "importance": 3,
        "reason": "Contacts with missing essential names can survive despite the contract constraints."
      },
      {
        "problem": "created_date is always NULL, so the required timestamp is unavailable even where a defensible recovery might exist in the contact history data.",
        "about": "data",
        "evidence_in_work": "cast(null as TIMESTAMP) as created_date",
        "source": "raw.contact_history ... \"_fivetran_start\", \"_fivetran_end\", \"_fivetran_synced\"",
        "importance": 2,
        "reason": "The direct source lacks this field, so NULL is understandable, but the unresolved mapping affects every contact."
      },
      {
        "problem": "Phone and photo length limits are checked after trimming rather than against the original values, potentially retaining values that the literal validation rules would nullify.",
        "about": "requirement",
        "evidence_in_work": "length(trim({col})) <= 50; length(trim(photo_url)) <= 500",
        "source": "LENGTH(assistant_phone) <= 50 ... on_failure: nullify_field",
        "importance": 1,
        "reason": "Only overlength values whose excess characters are surrounding spaces are affected."
      }
    ],
    "fewer_reason": "The final edits address foreign-key validation, email normalization, birthdate bounds, and optional-field trimming; only three remaining concrete concerns were identified."
  },
  "stg_salesforce__opportunity": {
    "items": [
      {
        "problem": "Closed-period flags are based only on close_date and can mark an open opportunity as closed this month or quarter.",
        "about": "requirement",
        "evidence_in_work": "(close_date is not null and year(close_date)=year(current_date) and month(close_date)=month(current_date)) as is_closed_this_month",
        "source": "Flag from stg_salesforce__opportunity indicating closed in the current month",
        "importance": 4,
        "reason": "These flags drive booking, lost-deal, and snapshot period metrics downstream."
      },
      {
        "problem": "days_to_close and closed-period flags may use the original raw close_date even when the projected close_date has been nullified as invalid.",
        "about": "data",
        "evidence_in_work": "case when ... then try_cast(close_date as date) else null end as close_date; date_diff('day', created_date::date, close_date::date)",
        "source": "close_date ... on_failure: nullify_field",
        "importance": 3,
        "reason": "DuckDB source-column precedence can leave internally inconsistent date-derived fields for invalid dates."
      },
      {
        "problem": "The close-date guard preserves a non-null close_date when created_date is NULL, although the contract's cross-field rule may require nullification in that case.",
        "about": "requirement",
        "evidence_in_work": "(created_date is null or try_cast(close_date as date) >= created_date::date)",
        "source": "close_date IS NULL OR close_date >= created_date::DATE",
        "importance": 2,
        "reason": "The implementation explicitly relaxes the supplied rule for missing creation dates."
      }
    ],
    "fewer_reason": "The final code fixes the earlier account mapping and implements the other explicit opportunity validations; three unresolved date-semantic concerns remain."
  },
  "stg_salesforce__user": {
    "items": [
      {
        "problem": "Username uniqueness is not enforced or checked independently of user_id uniqueness.",
        "about": "requirement",
        "evidence_in_work": "qualify row_number() over (partition by id order by id) = 1",
        "source": "username ... constraints: [not_null, unique]",
        "importance": 3,
        "reason": "Distinct users can still share a username, violating a separate contracted key."
      }
    ],
    "fewer_reason": "The foreign-key mapping errors were corrected and the remaining explicit user validations are implemented; only the separate username uniqueness requirement remains unchecked."
  },
  "stg_salesforce__lead": {
    "items": [
      {
        "problem": "Rows with NULL owner_id are not removed despite owner_id being required.",
        "about": "requirement",
        "evidence_in_work": "filters=['id is not null','last_name is not null','name is not null','status in ...']",
        "source": "owner_id ... constraints: [not_null]",
        "importance": 3,
        "reason": "Ownerless leads can survive staging and disappear from owner-based metrics."
      }
    ],
    "fewer_reason": "Status trimming and allowed-value filtering were fixed, and lead IDs were checked as unique; no further supported issue was identified."
  },
  "stg_salesforce__task": {
    "items": [],
    "fewer_reason": "The final implementation enforces the supplied required fields, status corrections, allowed statuses, types, and task-key uniqueness; no concrete remaining mismatch was found."
  },
  "stg_salesforce__event": {
    "items": [
      {
        "problem": "Events with a non-null end_date_time and NULL start_date_time are explicitly retained, which may relax the contract's end-after-start deletion rule.",
        "about": "requirement",
        "evidence_in_work": "(end_date_time is null or start_date_time is null or end_date_time >= start_date_time)",
        "source": "end_date_time IS NULL OR end_date_time >= start_date_time ... on_failure: delete_row",
