        "reason": "The interpretation of unknown comparisons changes which incomplete events survive."
      },
      {
        "problem": "Event IDs are deduplicated arbitrarily rather than distinguishing confirmed duplicate rows from conflicting records with the same ID.",
        "about": "data",
        "evidence_in_work": "row_number() over (partition by id order by id) = 1",
        "source": "Confirmed duplicates",
        "importance": 1,
        "reason": "No duplicate event IDs were observed, but conflicting future inputs would yield nondeterministic retained values."
      }
    ],
    "fewer_reason": "The final event edits implement the timestamp bounds and end-before-start filter; only two narrower special-case concerns remain."
  },
