  },
  "stg_salesforce__opportunity_line_item": {
    "items": [
      {
        "problem": "opportunity_id is populated from the line item's own id rather than raw.opportunity_line_item.opportunity_id.",
        "about": "data",
        "evidence_in_work": "mapping={... 'opportunity_id':'id' ...}",
        "source": "raw.opportunity_line_item ... \"id\" ... \"opportunity_id\"",
        "importance": 5,
        "reason": "The generated mapping is never corrected for line items and can break all opportunity enrichment."
      },
      {
        "problem": "product_2_id is populated from the line item's own id rather than its product foreign key.",
        "about": "data",
        "evidence_in_work": "mapping={... 'product_2_id':'id' ...}",
        "source": "raw.opportunity_line_item ... \"product_2_id\"",
        "importance": 5,
        "reason": "Product joins can fail for every line item."
      },
      {
        "problem": "Deleted line items are not filtered out.",
        "about": "requirement",
        "evidence_in_work": "if n=='stg_salesforce__opportunity_line_item': filters=['id is not null']",
        "source": "NOT COALESCE(is_deleted, false) ... on_failure: delete_row",
        "importance": 4,
        "reason": "This directly omits an explicit staging rule and admits deleted items into the mart."
      },
      {
        "problem": "The required unique, non-null mart line-item grain is not checked beyond filtering null IDs in staging.",
        "about": "data",
        "evidence_in_work": "filters=['id is not null']",
        "source": "opportunity_line_item_id ... tests: [not_null, unique]",
        "importance": 2,
        "reason": "Duplicate source IDs would propagate unchanged into the enhanced line-item result."
      }
    ],
    "fewer_reason": "Four supported issues were found; generic DECIMAL resolving to DECIMAL(18,3) is consistent with the downstream contract and is not treated as an error."
  },
  "stg_salesforce__order": {
    "items": [
      {
        "problem": "account_id is generated from the order's own id rather than raw.order_data.account_id.",
        "about": "data",
        "evidence_in_work": "mapping={... 'account_id':'id' ...}; from raw.{raw}",
        "source": "raw.order_data ... \"id\", \"account_id\"",
        "importance": 4,
        "reason": "The global mapping is not corrected for orders, replacing the account relationship for every row."
