    "fewer_reason": "The trajectory exposes the order fields but the supplied review specification omits the order-specific validation rules, so additional rule violations cannot be established."
  },
  "stg_salesforce__account_history": {
    "items": [
      {
        "problem": "created_date is inferred from _fivetran_start without validating that it represents the change timestamp intended by the contract.",
        "about": "data",
        "evidence_in_work": "try_cast(_fivetran_start as TIMESTAMP) as created_date",
        "source": "Daily snapshots ... the most recent non-deleted change",
        "importance": 3,
        "reason": "This choice determines snapshot days and which version is considered latest."
      },
      {
        "problem": "history_unique_key uniqueness depends on the unverified assumption that entity ID plus Fivetran start and end timestamps uniquely identifies a version.",
        "about": "data",
        "evidence_in_work": "md5(concat_ws('|', ... id ... _fivetran_start ... _fivetran_end ...))",
        "source": "history_unique_key ... constraints: [not_null, unique]",
        "importance": 1,
        "reason": "The current data passed uniqueness checks, but identical timestamp tuples are not handled explicitly."
      }
    ],
    "fewer_reason": "The earlier entity-level deduplication and invalid source-column reference were fixed; two remaining assumptions concern historical timestamp and version identity semantics."
  },
  "stg_salesforce__contact_history": {
    "items": [
      {
        "problem": "History is deduplicated by contact entity ID, discarding distinct historical versions rather than only duplicate history keys.",
        "about": "requirement",
        "evidence_in_work": "qualify row_number() over (partition by id order by id) = 1; stg_salesforce__contact_history (2434, 2434, 2434)",
        "source": "Cleaned contact history records tracking changes to contact data over time",
        "importance": 5,
        "reason": "The 3,000 raw rows shrink to 2,434, eliminating history needed for daily snapshots."
      },
      {
        "problem": "The surviving historical version is arbitrary because all rows within each deduplication partition have the same ordering value.",
        "about": "data",
        "evidence_in_work": "partition by id order by id",
        "source": "For each contact_id and snapshot_date, sort records by created_date descending",
        "importance": 4,
        "reason": "Even the single retained version need not be the latest or the correct version for any particular day."
      },
      {
        "problem": "created_date is inferred from _fivetran_start without checking that it is the intended contact-change timestamp.",
        "about": "data",
        "evidence_in_work": "try_cast(_fivetran_start as TIMESTAMP) as created_date",
        "source": "Daily snapshots ... latest non-deleted change per contact per calendar day",
        "importance": 3,
        "reason": "Snapshot dates depend entirely on this undocumented source mapping."
      }
    ],
    "fewer_reason": "Three concrete history-grain and timestamp concerns were found; the final account foreign-key mapping was corrected."
  },
  "stg_salesforce__opportunity_history": {
    "items": [
      {
        "problem": "The existing raw created_date is replaced with _fivetran_start rather than passed through or reconciled.",
        "about": "data",
        "evidence_in_work": "if name in ('created_date',) and n.endswith('_history'): expr='_fivetran_start'",
        "source": "raw.opportunity_history ... \"created_date\" ... \"_fivetran_start\"",
        "importance": 4,
        "reason": "This can change every opportunity snapshot date and its latest-record selection."
      },
      {
        "problem": "Historical probability values outside 0–100 are nullified even though the history contract specifies no such validation.",
        "about": "requirement",
        "evidence_in_work": "case when try_cast(probability as DECIMAL) between 0 and 100 then ... else null end as probability",
        "source": "probability ... data_type: DECIMAL",
        "importance": 2,
        "reason": "Historical values are altered beyond the supplied history rules."
      },
      {
        "problem": "last_modified_date is always NULL without resolving whether available Fivetran metadata provides the intended historical modification timestamp.",
        "about": "data",
        "evidence_in_work": "cast(null as TIMESTAMP) as last_modified_date",
        "source": "last_modified_date ... data_type: TIMESTAMP",
        "importance": 1,
        "reason": "The direct raw field is absent, but the output loses this attribute for all rows."
